<script setup lang="ts">
import {computed,onMounted,ref,toRaw} from 'vue'
import {ElMessageBox} from 'element-plus'
import {useRouter} from 'vue-router'
import {t as uiText} from '@/locales'
import PhoneObjectIdSelect from '@/components/PhoneObjectSelect/IdSelect.vue'
import ManufacturingObjectSelect from './ManufacturingObjectSelect.vue'
import {getManufacturingRelations,saveManufacturingRelation,type ManufacturingRelation,type ManufacturingRelationInput} from '@/api/modules/manufacturing'
import {getPhoneCompatibleMolds,type PhoneCompatibleMold} from '@/api/modules/phoneReference'
import {getMoldOptions} from '@/api/modules/molds'
import type {CompatiblePhone} from '@/types/molds'
import type {ProductLineOption} from '@/types/collaboration'
import {holeTypeNames} from '@/utils/engineeringPlan'
const props=defineProps<{phone:CompatiblePhone;editable:boolean}>()
const emit=defineEmits<{changed:[]}>()
const router=useRouter(),rows=ref<ManufacturingRelation[]>([]),total=ref(0),page=ref(1),keyword=ref(''),loading=ref(false),error=ref(''),editing=ref(false),saving=ref(false),current=ref<ManufacturingRelation>(),lines=ref<ProductLineOption[]>([]),molds=ref<PhoneCompatibleMold[]>([]),baseline=ref('')
type RelationDraft=Omit<ManufacturingRelationInput,'holeType'>&{holeType:ManufacturingRelationInput['holeType']|''}
const blank=():RelationDraft=>({productLineId:0,itemId:0,moldSetId:0,phoneModelId:props.phone.phoneModelId,holeType:'',structureDescription:'',sharedMaterial:false,manufacturingProductId:null,skuIds:[],moldEvidence:'',materialEvidence:'',compatibilityDigest:'',reason:'',status:'active'})
const form=ref<RelationDraft>(blank()),dirty=computed(()=>JSON.stringify(form.value)!==baseline.value)
const lineOptions=computed(()=>lines.value.map(row=>({type:'product_line',id:row.productLineId,code:row.productCode,name:row.productName,productLineId:row.productLineId})))
const moldOptions=computed(()=>molds.value.map(row=>({type:'mold',id:row.moldSetId,code:row.physicalCode,name:`${row.physicalCode||`ID #${row.moldSetId}`} · ${uiText('第{number}套',{number:row.setNo})} · ${row.moldName||row.styleName}`,subtitle:`${row.engravedCode||''} · ${row.parts.map(part=>`${part.partType} ${part.code}`).join(' / ')}`,phoneModels:[props.phone],data:row})))
const selectedMold=computed(()=>molds.value.find(row=>row.moldSetId===form.value.moldSetId))
const selectedProduct=computed(()=>current.value?.manufacturingProductId?[{id:current.value.manufacturingProductId,name:current.value.manufacturingProductName||'',code:current.value.manufacturingProductCode||''}]:[])
async function load(){loading.value=true;error.value='';try{const result=await getManufacturingRelations({phoneModelId:props.phone.phoneModelId,status:'all',keyword:keyword.value,page:page.value,size:20});rows.value=result.content;total.value=result.totalElements}catch(cause){error.value=cause instanceof Error?cause.message:'关系读取失败，请重试'}finally{loading.value=false}}
async function loadMolds(productLineId:number){molds.value=[];if(productLineId)molds.value=await getPhoneCompatibleMolds(props.phone.phoneModelId,productLineId)}
async function open(row?:ManufacturingRelation){error.value='';current.value=row;form.value=row?{version:row.version,productLineId:row.productLineId,itemId:row.itemId,moldSetId:row.moldSetId,phoneModelId:row.phoneModelId,holeType:row.holeType,structureDescription:row.structureDescription,sharedMaterial:row.sharedMaterial,manufacturingProductId:row.manufacturingProductId,skuIds:[...row.skuIds],moldEvidence:row.moldEvidence,materialEvidence:row.materialEvidence,compatibilityDigest:row.compatibilityDigest,reason:'',status:row.status}:blank();baseline.value=JSON.stringify(form.value);editing.value=true;try{const options=await getMoldOptions();lines.value=options.productLines;await loadMolds(form.value.productLineId)}catch(cause){error.value=cause instanceof Error?cause.message:'关联对象读取失败，请重试'}}
async function changeLine(id:number|null){form.value.productLineId=id||0;form.value.itemId=0;form.value.moldSetId=0;form.value.compatibilityDigest='';form.value.manufacturingProductId=null;form.value.skuIds=[];try{await loadMolds(id||0)}catch(cause){error.value=cause instanceof Error?cause.message:'实物套读取失败，请重试'}}
function chooseMold(id:number|null){const selected=molds.value.find(row=>row.moldSetId===id);form.value.moldSetId=id||0;form.value.itemId=selected?.itemId||0;form.value.compatibilityDigest=selected?.compatibilityDigest||''}
function shareMaterial(value:boolean){form.value.sharedMaterial=value;if(!value){form.value.manufacturingProductId=null;form.value.skuIds=[];form.value.materialEvidence=''}}
async function close(done?:()=>void){if(saving.value)return;if(dirty.value)try{await ElMessageBox.confirm(uiText('放弃尚未保存的工程关系修改？'),uiText('未保存修改'))}catch{return}editing.value=false;done?.()}
async function save(){error.value=relationFormIssue(form.value);if(error.value||!form.value.holeType)return;saving.value=true;try{await saveManufacturingRelation(current.value?.id||null,{...toRaw(form.value),holeType:form.value.holeType,skuIds:[...form.value.skuIds]});baseline.value=JSON.stringify(form.value);editing.value=false;emit('changed');await load()}catch(cause){error.value=cause instanceof Error?cause.message:'保存失败，请重新核对'}finally{saving.value=false}}
function relationFormIssue(value:RelationDraft){
 if(!value.productLineId||!value.moldSetId)return '请选择具体款式与已确认适配的实物套'
 if(!value.holeType)return '请明确孔型'
 if(value.structureDescription.length>1000)return '结构说明最多1000字'
 if(value.holeType==='other'&&!value.structureDescription.trim())return '其他孔型须填写具体结构说明'
 if(!value.moldEvidence.trim()||!value.reason.trim())return '请填写共模核对依据和本次变更原因'
 if(value.sharedMaterial&&(!value.manufacturingProductId||!value.skuIds.length||!value.materialEvidence.trim()))return '共用生产物料须明确原制造型号、SKU范围和成品共用依据'
 return ''
}
onMounted(load)
</script>
<template><section class="manufacturing-relations" aria-label="生产与模具关联"><header><h3>{{uiText('生产与模具关联')}}</h3><el-button v-if="editable" size="small" type="primary" @click="open()">{{uiText('新增工程确认关系')}}</el-button></header><p>{{uiText('手机资料编码不变；每条关系只适用于明确款式、孔型、实物套和SKU范围，不是全局替代码。')}}</p><div class="tools"><el-input v-model="keyword" :placeholder="uiText('搜索款式、制造编码或模具')" @keyup.enter="page=1;load()"/><el-button @click="page=1;load()">{{uiText('查询')}}</el-button></div><el-alert v-if="error&&!editing" :title="uiText(error)" type="error" :closable="false"><el-button link @click="load">{{uiText('重试')}}</el-button></el-alert><div v-loading="loading"><article v-for="row in rows" :key="row.id"><strong>{{row.moldName||row.styleName}} · {{uiText(holeTypeNames[row.holeType])}} · {{row.status==='active'?uiText('有效'):uiText('已停用')}}</strong><p>{{phone.modelName}}（{{phone.phoneModelCode}}） → {{uiText('制造编码')}} {{row.manufacturingPhoneCode||uiText('独立物料待确认')}} · {{uiText('实物套')}} {{row.physicalCode||`ID #${row.moldSetId}`}}<template v-if="row.setNo"> · {{row.setNo}}</template></p><small>{{uiText('已保存关联，实际采用时重新核对')}}</small><p>{{row.sharedMaterial?uiText('共用生产物料，使用同一份库存'):uiText('仅确认共模，不代表共用成品或库存')}}</p><p v-if="row.skus?.length">SKU：{{row.skus.map(sku=>`${sku.code} · ${sku.name}`).join('；')}}</p><small>{{uiText('结构说明')}}：{{row.structureDescription||'—'}}</small><small>{{uiText('共模依据')}}：{{row.moldEvidence}}</small><small v-if="row.sharedMaterial">{{uiText('成品共用依据')}}：{{row.materialEvidence}}</small><div class="tools"><el-button link @click="router.push({path:'/molds',query:{itemId:row.itemId,moldSetId:row.moldSetId,tab:'compatiblePhones'}})">{{uiText('查看模具及原刻码')}}</el-button><el-button v-if="editable&&row.canWrite!==false" link @click="open(row)">{{uiText('维护关系')}}</el-button></div></article><p v-if="!rows.length&&!loading">{{uiText('暂无已确认的制造关系。共模与共用成品须分别核对，不按手机名称自动建立。')}}</p></div><el-pagination small layout="total,prev,pager,next" :total="total" :current-page="page" :page-size="20" @current-change="page=$event;load()"/>
<el-dialog :model-value="editing" :title="uiText(current?'维护工程确认关系':'新增工程确认关系')" width="min(860px,96vw)" top="20px" append-to-body :close-on-click-modal="false" :show-close="!saving" :before-close="close" class="manufacturing-relation-dialog"><el-alert v-if="error" :title="uiText(error)" type="error" :closable="false"/><el-form label-position="top" :disabled="saving"><el-form-item :label="uiText('实际适用手机')">{{phone.brandName}} · {{phone.modelName}} · {{uiText('手机编码')}} {{phone.phoneModelCode}}</el-form-item><el-form-item :label="uiText('具体款式')" required><PhoneObjectIdSelect :model-value="form.productLineId||null" :options="lineOptions" type="product_line" :phone-first="false" :label="uiText('具体款式')" @update:model-value="changeLine"/></el-form-item><el-form-item :label="uiText('具体实物套及原刻码')" required><PhoneObjectIdSelect :model-value="form.moldSetId||null" :options="moldOptions" type="mold" :disabled="!form.productLineId" :label="uiText('具体实物套及原刻码')" @update:model-value="chooseMold"/><small v-if="selectedMold" class="selected-mold-identity">{{selectedMold.physicalCode||`ID #${selectedMold.moldSetId}`}} · {{uiText('第{number}套',{number:selectedMold.setNo})}} · {{selectedMold.parts.map(part=>`${part.partType} ${part.code}`).join(' ／ ')}}</small><small>{{uiText('仅列本手机PC／TPU已确认可用的具体套。缺少适配请先在原模具详情维护，不自动确认。')}}</small></el-form-item><el-form-item :label="uiText('孔型')" required><el-select v-model="form.holeType" :aria-label="uiText('工程关系孔型')"><el-option v-for="(label,value) in holeTypeNames" :key="value" :value="value" :label="uiText(label)"/></el-select></el-form-item><el-form-item :label="uiText('结构说明')" :required="form.holeType==='other'"><el-input v-model="form.structureDescription" maxlength="1000"/></el-form-item><el-form-item :label="uiText('共模核对依据')" required><el-input v-model="form.moldEvidence" type="textarea" :autosize="{minRows:2,maxRows:5}" maxlength="2000"/></el-form-item><el-checkbox :model-value="form.sharedMaterial" @update:model-value="shareMaterial(Boolean($event))">{{uiText('另已确认最终实物、加工要求及BOM可共用生产物料')}}</el-checkbox><p>{{uiText('不勾选时只确认共模，绝不合并成品或库存。')}}</p><template v-if="form.sharedMaterial"><el-form-item :label="uiText('沿用的原制造型号产品')" required><ManufacturingObjectSelect :model-value="form.manufacturingProductId?[form.manufacturingProductId]:[]" kind="products" :product-line-id="form.productLineId" :known="selectedProduct" :label="uiText('沿用的原制造型号产品')" :disabled="!form.productLineId" @update:model-value="form.manufacturingProductId=$event[0]||null;form.skuIds=[]"/></el-form-item><el-form-item :label="uiText('明确可共用的SKU范围')" required><ManufacturingObjectSelect :model-value="form.skuIds" kind="skus" :multiple="true" :product-line-id="form.productLineId" :manufacturing-product-id="form.manufacturingProductId||undefined" :known="current?.skus" :label="uiText('明确可共用的SKU范围')" :disabled="!form.manufacturingProductId" @update:model-value="form.skuIds=$event"/></el-form-item><el-form-item :label="uiText('最终成品共用依据')" required><el-input v-model="form.materialEvidence" type="textarea" :autosize="{minRows:2,maxRows:5}" maxlength="2000"/></el-form-item></template><el-form-item :label="uiText('关系状态')"><el-select v-model="form.status"><el-option value="active" :label="uiText('有效')"/><el-option value="inactive" :label="uiText('停用，保留历史')"/></el-select></el-form-item><el-form-item :label="uiText('本次变更原因')" required><el-input v-model="form.reason" type="textarea" :autosize="{minRows:2,maxRows:4}" maxlength="2000"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="close()">{{uiText('取消')}}</el-button><el-button type="primary" :loading="saving" @click="save">{{uiText('保存工程确认关系')}}</el-button></template></el-dialog></section></template>
<style scoped>.manufacturing-relations{margin-top:16px;border-top:1px solid var(--el-border-color-light);padding-top:12px;font-size:12px}.manufacturing-relations header{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.manufacturing-relations h3{font-size:14px;margin:0}.manufacturing-relations article{padding:10px 0;border-bottom:1px solid var(--el-border-color-light);overflow-wrap:anywhere}.manufacturing-relations p{line-height:1.6;margin:6px 0}.manufacturing-relations small{display:block;color:var(--el-text-color-secondary);line-height:1.6}.tools{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.tools>.el-input{flex:1;min-width:150px}:global(.manufacturing-relation-dialog){display:flex;flex-direction:column;max-height:calc(100dvh - 40px);margin-bottom:20px}:global(.manufacturing-relation-dialog>.el-dialog__body){min-height:0;overflow:auto}:global(.manufacturing-relation-dialog .el-form-item__label){font-size:12px}:global(.manufacturing-relation-dialog .el-select){width:100%}:global(.manufacturing-relation-dialog>.el-dialog__footer){display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap}</style>
